import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { InlineBadgeProps } from "./inline-badge.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

const componentName = "InlineBadge";

export const InlineBadgeClasses = {
  root: "exp-textura_inline-badge",
  sm: "exp-textura_inline-badge_sm",
};

const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  beta: {
    root: {
      backgroundColor: theme.badgeInline.default.beta.color.background,
      color: theme.badgeInline.default.beta.color.content,
      height: theme.toRem(20),
      ...theme.typography.body.smAccent,
    },
    sm: {
      height: theme.toRem(15),
      ...theme.typography.micro.smEmphasis,
    },
  },
  new: {
    root: {
      backgroundColor: theme.badgeInline.default.new.color.background,
      color: theme.badgeInline.default.new.color.content,
      height: theme.toRem(20),
      ...theme.typography.body.smAccent,
    },
    sm: {
      height: theme.toRem(15),
      ...theme.typography.micro.smEmphasis,
    },
  },
  neutral: {
    root: {
      backgroundColor: theme.badgeInline.default.neutral.color.background,
      color: theme.badgeInline.default.neutral.color.content,
      height: theme.toRem(20),
      ...theme.typography.body.smAccent,
    },
    sm: {
      height: theme.toRem(15),
      ...theme.typography.micro.smEmphasis,
    },
  },
  inverse: {
    root: {
      backgroundColor: theme.badgeInline.inverse.bodyText.color.background,
      color: theme.badgeInline.inverse.bodyText.color.content,
    },
  },
  betaInverse: {
    root: {
      backgroundColor: theme.badgeInline.inverse.beta.color.background,
      color: theme.badgeInline.inverse.beta.color.content,
      height: theme.toRem(20),
      ...theme.typography.body.smAccent,
    },
    sm: {
      height: theme.toRem(15),
      ...theme.typography.micro.smEmphasis,
    },
  },
  newInverse: {
    root: {
      backgroundColor: theme.badgeInline.inverse.new.color.background,
      color: theme.badgeInline.inverse.new.color.content,
      height: theme.toRem(20),
      ...theme.typography.body.smAccent,
    },
    sm: {
      height: theme.toRem(15),
      ...theme.typography.micro.smEmphasis,
    },
  },
  neutralInverse: {
    root: {
      backgroundColor: theme.badgeInline.inverse.neutral.color.background,
      color: theme.badgeInline.inverse.neutral.color.content,
      height: theme.toRem(20),
      ...theme.typography.body.smAccent,
    },
    sm: {
      height: theme.toRem(15),
      ...theme.typography.micro.smEmphasis,
    },
  },
  critical: {
    root: {
      backgroundColor: theme.badgeInline.default.critical.color.background,
      color: theme.badgeInline.default.critical.color.content,
      height: theme.toRem(20),
      ...theme.typography.body.smAccent,
    },
    sm: {
      height: theme.toRem(15),
      ...theme.typography.micro.smEmphasis,
    },
  },
  criticalInverse: {
    root: {
      backgroundColor: theme.badgeInline.inverse.critical.color.background,
      color: theme.badgeInline.inverse.critical.color.content,
      height: theme.toRem(20),
      ...theme.typography.body.smAccent,
    },
    sm: {
      height: theme.toRem(15),
      ...theme.typography.micro.smEmphasis,
    },
  },
});

const generateStyles = (props: InlineBadgeProps): CSSObject => {
  const { currentTheme: theme, variant = "default", styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<InlineBadgeProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    gap: theme.toRem(theme.spacing[4]),
    borderRadius: theme.toRem(2),
    whiteSpace: "nowrap",
    padding: `${theme.toRem(2)} ${theme.toRem(theme.spacing[4])}`,
    backgroundColor: theme.badgeInline.default.bodyText.color.background,
    color: theme.badgeInline.default.bodyText.color.content,
    ...theme.typography.body.md,

    [`&.${InlineBadgeClasses.sm}`]: {
      ...theme.typography.body.sm,
      height: theme.toRem(20),
      ...styleSlots?.sm,
    },

    ...styleSlots?.root,
  };
};

const excludedDOMProps = getExcludedDOMProps();

export const StyledInlineBadge = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<InlineBadgeProps>((props) => generateStyles(props));
